<?php $title='So sánh phiên bản'; ?>
<div class="page-head"><div><span class="eyebrow">DIFF</span><h1>So sánh v<?= (int)$result['left']['version_number'] ?> → v<?= (int)$result['right']['version_number'] ?></h1><p><?= e($result['left']['status']) ?> → <?= e($result['right']['status']) ?></p></div><a class="button" href="<?= e(url('versions')) ?>">Quay lại</a></div><section class="panel"><div class="panel-head"><div><h2>Thay đổi cấu hình</h2><p>Các giá trị trước và sau theo từng feature.</p></div></div><?php if(!$result['diff']): ?><p class="empty">Hai snapshot giống nhau.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Feature</th><th>Trường</th><th>Trước</th><th>Sau</th></tr></thead><tbody><?php foreach($result['diff'] as $key=>$changes): foreach($changes as $field=>$change): ?><tr><td><code><?= e($key) ?></code></td><td><?= e($field) ?></td><td><?= e(is_scalar($change['before'])?(string)$change['before']:json_encode($change['before'],JSON_UNESCAPED_UNICODE)) ?></td><td><strong><?= e(is_scalar($change['after'])?(string)$change['after']:json_encode($change['after'],JSON_UNESCAPED_UNICODE)) ?></strong></td></tr><?php endforeach; endforeach; ?></tbody></table></div><?php endif; ?></section>
